def format_timestamp(
    ts: int | float | tuple | time.struct_time | datetime.datetime,
) -> str:
    """Formats a timestamp in the format used by HTTP.

    The argument may be a numeric timestamp as returned by `time.time`,
    a time tuple as returned by `time.gmtime`, or a `datetime.datetime`
    object. Naive `datetime.datetime` objects are assumed to represent
    UTC; aware objects are converted to UTC before formatting.

    >>> format_timestamp(1359312200)
    'Sun, 27 Jan 2013 18:43:20 GMT'
    """
    if isinstance(ts, (int, float)):
        time_num = ts
    elif isinstance(ts, (tuple, time.struct_time)):
        time_num = calendar.timegm(ts)
    elif isinstance(ts, datetime.datetime):
        time_num = calendar.timegm(ts.utctimetuple())
    else:
        raise TypeError("unknown timestamp type: %r" % ts)
    return email.utils.formatdate(time_num, usegmt=True)

def raises(
        self, func: Callable[_P, _R], *, _test: Callable[[ExceptionTrap], bool] = bool
    ) -> functools._Wrapped[_P, _R, _P, bool]:
        """
        Wrap func and replace the result with the truth
        value of the trap (True if an exception occurred).

        Decorate a function that always fails.

        >>> @ExceptionTrap(ValueError).raises
        ... def fail():
        ...     raise ValueError('failed')
        >>> fail()
        True
        """

        @functools.wraps(func)
        def wrapper(*args: _P.args, **kwargs: _P.kwargs) -> bool:
            with ExceptionTrap(self.exceptions) as trap:
                func(*args, **kwargs)
            return _test(trap)

        return wrapper

def matrix_multiply(a, b):
    """Multiply two matrices (lists of lists).

    >>> matrix_multiply([[1, 2]], [[3], [4]])
    [[11]]
    """
    if not a or not b or len(a[0]) != len(b):
        raise ValueError("dimension mismatch")
    cols = len(b[0])
    out = []
    for row in a:
        acc = [0] * cols
        for k, rk in enumerate(row):
            for j in range(cols):
                acc[j] += rk * b[k][j]
        out.append(acc)
    return out

